-- Server-side discovery functions used by public directories.

create or replace function public.discover_professionals(p_lat double precision default null,p_lng double precision default null,p_radius double precision default null,p_category_ids uuid[] default null,p_q text default null,p_location text default null,p_rating numeric default null,p_price_min numeric default null,p_price_max numeric default null,p_sort text default 'relevance',p_offset integer default 0,p_limit integer default 24) returns table(item jsonb,total_count bigint) language sql stable security definer set search_path=public as $$ with base as (select p.*,(select avg(s.price) from public.services s where s.professional_id=p.id and s.is_active=true) avg_price,case when p_lat is not null and p_lng is not null and p.latitude is not null and p.longitude is not null then 6371*2*asin(sqrt(power(sin(radians(p.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(p.latitude))*power(sin(radians(p.longitude-p_lng)/2),2))) end distance_km,coalesce((select jsonb_agg(to_jsonb(c) order by c.name) from public.professional_categories pc join public.categories c on c.id=pc.category_id where pc.professional_id=p.id),'[]'::jsonb) categories from public.professionals p where p.status='active' and(p_category_ids is null or exists(select 1 from public.professional_categories pc where pc.professional_id=p.id and pc.category_id=any(p_category_ids))) and(nullif(trim(p_q),'') is null or p.full_name ilike '%'||p_q||'%' or coalesce(p.professional_name,'') ilike '%'||p_q||'%' or coalesce(p.bio,'') ilike '%'||p_q||'%') and(nullif(trim(p_location),'') is null or coalesce(p.address,'') ilike '%'||p_location||'%') and(p_rating is null or coalesce(p.rating_avg,0)>=p_rating)),filtered as(select * from base where(p_radius is null or distance_km<=p_radius) and(p_price_min is null or avg_price>=p_price_min) and(p_price_max is null or avg_price<=p_price_max)),ranked as(select *,count(*) over() cnt from filtered order by case when p_sort='rating' then rating_avg end desc nulls last,case when p_sort='reviews' then review_count end desc nulls last,case when p_sort='newest' then extract(epoch from created_at) end desc nulls last,case when p_sort='price_asc' then avg_price end asc nulls last,case when p_sort='price_desc' then avg_price end desc nulls last,case when p_sort in('distance','relevance') and p_lat is not null then distance_km end asc nulls last,case when p_sort='relevance' and p_lat is null then rating_avg end desc nulls last,id offset greatest(p_offset,0) limit least(greatest(p_limit,1),100)) select to_jsonb(ranked)-'avg_price'-'distance_km'-'categories'-'cnt'||jsonb_build_object('averagePrice',avg_price,'distanceKm',distance_km,'categories',categories),cnt from ranked $$;
revoke all on function public.discover_professionals(double precision,double precision,double precision,uuid[],text,text,numeric,numeric,numeric,text,integer,integer) from public,anon,authenticated;

create or replace function public.discover_spaces(p_lat double precision default null,p_lng double precision default null,p_radius double precision default null,p_category_ids uuid[] default null,p_q text default null,p_location text default null,p_rating numeric default null,p_price_min numeric default null,p_price_max numeric default null,p_sort text default 'relevance',p_offset integer default 0,p_limit integer default 24) returns table(item jsonb,total_count bigint) language sql stable security definer set search_path=public as $$ with base as(select s.*,(select avg(r.price_per_hour) from public.space_rooms r where r.space_id=s.id and r.is_active=true) avg_price,case when p_lat is not null and p_lng is not null and s.latitude is not null and s.longitude is not null then 6371*2*asin(sqrt(power(sin(radians(s.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(s.latitude))*power(sin(radians(s.longitude-p_lng)/2),2))) end distance_km,coalesce((select jsonb_agg(to_jsonb(c) order by c.name) from public.space_categories sc join public.categories c on c.id=sc.category_id where sc.space_id=s.id),'[]'::jsonb) categories from public.sport_spaces s where s.status='active' and(p_category_ids is null or exists(select 1 from public.space_categories sc where sc.space_id=s.id and sc.category_id=any(p_category_ids))) and(nullif(trim(p_q),'') is null or s.name ilike '%'||p_q||'%' or coalesce(s.description,'') ilike '%'||p_q||'%' or coalesce(s.address,'') ilike '%'||p_q||'%') and(nullif(trim(p_location),'') is null or coalesce(s.address,'') ilike '%'||p_location||'%') and(p_rating is null or coalesce(s.rating_avg,0)>=p_rating)),filtered as(select * from base where(p_radius is null or distance_km<=p_radius) and(p_price_min is null or avg_price>=p_price_min) and(p_price_max is null or avg_price<=p_price_max)),ranked as(select *,count(*) over() cnt from filtered order by case when p_sort='rating' then rating_avg end desc nulls last,case when p_sort='reviews' then review_count end desc nulls last,case when p_sort='newest' then extract(epoch from created_at) end desc nulls last,case when p_sort='price_asc' then avg_price end asc nulls last,case when p_sort='price_desc' then avg_price end desc nulls last,case when p_sort in('distance','relevance') and p_lat is not null then distance_km end asc nulls last,case when p_sort='relevance' and p_lat is null then rating_avg end desc nulls last,id offset greatest(p_offset,0) limit least(greatest(p_limit,1),100)) select to_jsonb(ranked)-'avg_price'-'distance_km'-'categories'-'cnt'||jsonb_build_object('averagePrice',avg_price,'distanceKm',distance_km,'categories',categories),cnt from ranked $$;
revoke all on function public.discover_spaces(double precision,double precision,double precision,uuid[],text,text,numeric,numeric,numeric,text,integer,integer) from public,anon,authenticated;

create or replace function public.discover_events(p_lat double precision default null,p_lng double precision default null,p_radius double precision default null,p_category_ids uuid[] default null,p_q text default null,p_location text default null,p_date_from timestamptz default null,p_date_to timestamptz default null,p_price_min numeric default null,p_price_max numeric default null,p_sort text default 'upcoming',p_offset integer default 0,p_limit integer default 24) returns table(item jsonb,total_count bigint) language sql stable security definer set search_path=public as $$ with base as(select e.*,case when p_lat is not null and p_lng is not null and e.latitude is not null and e.longitude is not null then 6371*2*asin(sqrt(power(sin(radians(e.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(e.latitude))*power(sin(radians(e.longitude-p_lng)/2),2))) end distance_km,case when e.category_id is not null then(select to_jsonb(c) from public.categories c where c.id=e.category_id) end category from public.events e where e.status='published' and e.start_date>=now() and(p_category_ids is null or e.category_id=any(p_category_ids)) and(nullif(trim(p_q),'') is null or e.title ilike '%'||p_q||'%' or coalesce(e.description,'') ilike '%'||p_q||'%' or coalesce(e.address,'') ilike '%'||p_q||'%') and(nullif(trim(p_location),'') is null or coalesce(e.address,'') ilike '%'||p_location||'%') and(p_date_from is null or e.start_date>=p_date_from) and(p_date_to is null or e.start_date<=p_date_to) and(p_price_min is null or coalesce(e.price_min,0)>=p_price_min) and(p_price_max is null or coalesce(e.price_min,0)<=p_price_max)),filtered as(select * from base where p_radius is null or distance_km<=p_radius),ranked as(select *,count(*) over() cnt from filtered order by case when p_sort='upcoming' then extract(epoch from start_date) end asc,case when p_sort='distance' then distance_km end asc nulls last,case when p_sort='popular' then views_count end desc nulls last,case when p_sort='newest' then extract(epoch from created_at) end desc,case when p_sort='price_asc' then price_min end asc nulls last,case when p_sort='price_desc' then price_min end desc nulls last,start_date,id offset greatest(p_offset,0) limit least(greatest(p_limit,1),100)) select to_jsonb(ranked)-'distance_km'-'category'-'cnt'||jsonb_build_object('distanceKm',distance_km,'category',category),cnt from ranked $$;
revoke all on function public.discover_events(double precision,double precision,double precision,uuid[],text,text,timestamptz,timestamptz,numeric,numeric,text,integer,integer) from public,anon,authenticated;

create or replace function public.discover_communities(p_lat double precision default null,p_lng double precision default null,p_category_ids uuid[] default null,p_q text default null,p_sort text default 'newest',p_offset integer default 0,p_limit integer default 24) returns table(item jsonb,total_count bigint) language sql stable security definer set search_path=public as $$ with base as(select c.*,(select count(*) from public.community_members cm where cm.community_id=c.id) member_count,case when p_lat is not null and p_lng is not null and c.latitude is not null and c.longitude is not null then 6371*2*asin(sqrt(power(sin(radians(c.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(c.latitude))*power(sin(radians(c.longitude-p_lng)/2),2))) end distance_km,coalesce((select jsonb_agg(to_jsonb(cat) order by cat.name) from public.community_categories cc join public.categories cat on cat.id=cc.category_id where cc.community_id=c.id),'[]'::jsonb) categories from public.communities c where(p_category_ids is null or exists(select 1 from public.community_categories cc where cc.community_id=c.id and cc.category_id=any(p_category_ids))) and(nullif(trim(p_q),'') is null or c.name ilike '%'||p_q||'%' or coalesce(c.description,'') ilike '%'||p_q||'%' or coalesce(c.address,'') ilike '%'||p_q||'%')),ranked as(select *,count(*) over() cnt from base order by case when p_sort='members' then member_count end desc,case when p_sort='name' then name end asc,case when p_sort='distance' then distance_km end asc nulls last,case when p_sort='newest' then extract(epoch from created_at) end desc,created_at desc,id offset greatest(p_offset,0) limit least(greatest(p_limit,1),100)) select to_jsonb(ranked)-'member_count'-'distance_km'-'categories'-'cnt'||jsonb_build_object('memberCount',member_count,'distanceKm',distance_km,'categories',categories),cnt from ranked $$;
revoke all on function public.discover_communities(double precision,double precision,uuid[],text,text,integer,integer) from public,anon,authenticated;

insert into public.community_categories(community_id,category_id) select c.id,cat.id from public.communities c join public.categories cat on lower(cat.name)=lower(c.sport_category) where c.sport_category is not null and not exists(select 1 from public.community_categories cc where cc.community_id=c.id) on conflict do nothing;
